import { getRequestHeaders } from "h3";
import { computeSignature, HMAC_SHA256, ensureConfiguration, readRawBodyClone } from "../helpers.js";
const MAX_VALID_TIME_DIFFERENCE = 5;
const PADDLE_SIGNATURE = "paddle-signature";
const extractHeaders = (header) => {
  const parts = header.split(";");
  let ts = "";
  let h1 = "";
  for (const part of parts) {
    const [key, value] = part.split("=");
    if (value) {
      if (key === "ts") ts = value;
      else if (key === "h1") h1 = value;
    }
  }
  if (!(ts && h1)) return null;
  return { ts: Number.parseInt(ts), h1 };
};
export const isValidPaddleWebhook = async (event) => {
  const config = ensureConfiguration("paddle", event);
  const headers = getRequestHeaders(event);
  const body = await readRawBodyClone(event);
  const paddleSignature = headers[PADDLE_SIGNATURE];
  if (!body || !paddleSignature) return false;
  const signatureHeaders = extractHeaders(paddleSignature);
  if (!signatureHeaders) return false;
  const { ts: webhookTimestamp, h1: webhookSignature } = signatureHeaders;
  if ((/* @__PURE__ */ new Date()).getTime() > new Date((webhookTimestamp + MAX_VALID_TIME_DIFFERENCE) * 1e3).getTime()) return false;
  const payloadWithTime = `${webhookTimestamp}:${body}`;
  const computedHash = await computeSignature(config.webhookId, HMAC_SHA256, payloadWithTime);
  return computedHash === webhookSignature;
};
